{
  "status": "AUTHORIZED_UNIQUE",
  "coverage": [
    {
      "text": "往前",
      "role": "ACTION",
      "explanation": "Imperative direction meaning forward; together with the following quantity it selects the legal action walk_forward. It requests motion toward the front before anything else."
    },
    {
      "text": "八米",
      "role": "QUANTITY",
      "explanation": "Specifies the distance for the preceding forward movement as 8 meters, a positive finite distance_m value."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Clause punctuation dividing the forward-movement instruction from the next instruction; it does not itself request an action."
    },
    {
      "text": "然后",
      "role": "RELATION",
      "explanation": "Explicit sequencing relation meaning after that; it orders the quoted stop after the forward movement."
    },
    {
      "text": "‘停’",
      "role": "ACTION",
      "explanation": "Quoted Chinese imperative for stop; it selects the legal action stop. The quotes are not content modifiers because the later clause says they do not affect the stop instruction."
    },
    {
      "text": "，",
      "role": "SEPARATOR",
      "explanation": "Clause punctuation separating the stop action from the clarifying clause; it does not itself request an action."
    },
    {
      "text": "引号不影响让你停",
      "role": "CONTEXT",
      "explanation": "Clarifies that the quotation marks around 停 do not change the command to stop. It reinforces rather than replaces or duplicates the preceding stop action, and adds no new action or order."
    },
    {
      "text": "。",
      "role": "SEPARATOR",
      "explanation": "Sentence-final punctuation terminating the source; it does not modify authority."
    }
  ],
  "dimensions": {
    "action_multiplicity": {
      "status": "UNIQUE",
      "explanation": "The source requests exactly two actions: a forward walk of 8 meters and a stop. The quoted 停 is the stop action, and the final clause clarifies that quotation does not change it; it does not add a third action or replace the forward walk."

